{"content":"@font-face {
  font-family: 'Anton';
  src: url('./fonts/Anton-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Pacifico';
  src: url('./fonts/Pacifico-Regular.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #0e0716;
  --panel: #1a0f28;
  --panel-2: #221338;
  --ink: #f7f2ea;
  --muted: #b9a8cc;
  --pink: #ff2e88;
  --neon: #ff7ad9;
  --amber: #ffb347;
  --line: #3a2352;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 20px;
  background: linear-gradient(90deg, #2a0f3d, #4a1042 55%, #7a1e3c);
  border-bottom: 3px solid var(--pink);
}
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  font-family: 'Anton', sans-serif;
  font-size: 30px;
  line-height: 1;
  color: #fff;
  background: var(--pink);
  border-radius: 10px;
  padding: 8px 10px;
  transform: rotate(-4deg);
  box-shadow: 0 0 18px rgba(255, 46, 136, 0.55);
}
.brand h1 {
  font-family: 'Anton', sans-serif;
  font-size: 26px;
  letter-spacing: 1px;
  margin: 0;
  text-transform: uppercase;
}
.brand h1 span { color: var(--amber); }
.brand p { margin: 2px 0 0; color: #e8d8f5; font-size: 13px; }

.export-btn {
  font-family: 'Anton', sans-serif;
  font-size: 18px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #1a0a24;
  background: linear-gradient(180deg, #ffd94d, #ffb347);
  border: none;
  border-radius: 10px;
  padding: 12px 22px;
  cursor: pointer;
  box-shadow: 0 4px 0 #b97e14, 0 8px 22px rgba(0, 0, 0, 0.4);
}
.export-btn:hover { filter: brightness(1.07); }
.export-btn:active { transform: translateY(2px); box-shadow: 0 2px 0 #b97e14; }

.studio {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 18px;
  padding: 18px 20px;
  flex: 1;
  align-items: start;
}
.controls {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 6px 16px 16px;
}
.group { padding: 12px 0; border-bottom: 1px solid var(--line); }
.group:last-child { border-bottom: none; }
.group h2 {
  font-family: 'Anton', sans-serif;
  font-size: 15px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--amber);
  margin: 0 0 10px;
}
.btn-row { display: flex; flex-wrap: wrap; gap: 8px; }
.pill {
  background: var(--panel-2);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 13px;
  cursor: pointer;
}
.pill:hover { border-color: var(--pink); }
.pill.active { background: var(--pink); border-color: var(--pink); color: #fff; }
.pill small { display: block; color: var(--muted); font-size: 11px; }
.pill.active small { color: #ffd6ea; }

.upload-btn, .ghost-btn {
  display: inline-block;
  background: var(--pink);
  color: #fff;
  border: none;
  border-radius: 9px;
  padding: 9px 14px;
  font-size: 14px;
  cursor: pointer;
  margin: 0 8px 8px 0;
}
.ghost-btn { background: var(--panel-2); border: 1px solid var(--line); color: var(--ink); }
.ghost-btn:hover { border-color: var(--pink); }
.hint { color: var(--muted); font-size: 12px; line-height: 1.5; margin: 4px 0 0; }

.tray { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 4px; }
.tray:empty { display: none; }
.thumb {
  width: 72px;
  height: 54px;
  object-fit: cover;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
}
.thumb.selected { border-color: var(--amber); box-shadow: 0 0 0 2px rgba(255, 179, 71, 0.4); }
.thumb.assigned { border-color: var(--pink); }

.field { display: block; font-size: 13px; color: var(--muted); margin-bottom: 10px; }
.field input[type="text"], .field select {
  display: block;
  width: 100%;
  margin-top: 4px;
  background: #120a1e;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 14px;
}
.field input[type="range"] { width: 100%; accent-color: var(--pink); }
.check { display: block; font-size: 13px; margin: 6px 0 10px; cursor: pointer; }
.check input { accent-color: var(--pink); }

.preview-wrap { min-width: 0; }
.preview-bar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 10px;
}
.preview-bar #sizeLabel { font-family: 'Anton', sans-serif; letter-spacing: 1px; color: var(--ink); text-transform: uppercase; }
.canvas-holder {
  background: #05030a;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
  display: flex;
  justify-content: center;
}
#previewCanvas {
  max-width: 100%;
  max-height: calc(100vh - 260px);
  border-radius: 6px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.55);
  cursor: grab;
  touch-action: none;
}
#previewCanvas.dragging { cursor: grabbing; }
.preview-hint { color: var(--muted); font-size: 12px; text-align: center; }

.foot {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 20px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

@media (max-width: 900px) {
  .studio { grid-template-columns: 1fr; }
