{"content":"// CDP play-test for Vice Coast Cover Studio (test driver, lives in /tmp only).
// Drives headless Chromium over the DevTools protocol with Node's global
// WebSocket: loads the editor with demo photos, switches layout + size,
// clicks Export PNG, and checks the downloaded file is a real 1920x1080 PNG.
import { execFile } from 'node:child_process';
import { mkdirSync, readdirSync, readFileSync } from 'node:fs';

const CHROME = `${process.env.HOME}/.cache/ms-playwright/chromium-1148/chrome-linux/chrome`;
const PORT = 9333;
const DL = '/tmp/vc-downloads';
mkdirSync(DL, { recursive: true });

const chrome = execFile(CHROME, [
  '--headless=new', '--disable-gpu', '--no-sandbox',
  `--remote-debugging-port=${PORT}`,
  '--user-data-dir=/tmp/vc-profile',
  'about:blank',
], () => {});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getTarget() {
  for (let i = 0; i < 30; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const targets = await res.json();
      const page = targets.find((t) => t.type === 'page');
      if (page) return page;
    } catch {}
    await sleep(500);
  }
  throw new Error('no CDP page target');
}

let id = 0;
const pending = new Map();
let ws;
function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const mid = ++id;
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
}
async function evalJs(expression) {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error('page JS error: ' + JSON.stringify(r.exceptionDetails));
  return r.result.value;
}

const target = await getTarget();
ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});
ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id).resolve(msg.result ?? {});
    pending.delete(msg.id);
  }
};

await send('Page.enable');
await send('Runtime.enable');
await send('Browser.setDownloadBehavior', { behavior: 'allow', downloadPath: DL, eventsEnabled: true });
await send('Page.navigate', { url: 'http://localhost:8080/?demo=1' });

// wait for the demo photos to load into the editor
let status = '';
for (let i = 0; i < 40; i++) {
  status = await evalJs(`document.getElementById('statusLabel').textContent`);
  if (status.includes('3 photos')) break;
  await sleep(500);
}
console.log('status after demo load:', JSON.stringify(status));
if (!status.includes('3 photos')) throw new Error('demo photos did not load');

// no network requests outside the local server
const outside = await evalJs(
  `performance.getEntriesByType('resource').map(r => r.name).filter(n => !n.startsWith('http://localhost:8080'))`,
);
console.log('non-local resources:', JSON.stringify(outside));

// switch layout to Four Up, then size to Square, then back to Wide
await evalJs(`[...document.querySelectorAll('#layoutBtns .pill')].find(b => b.textContent.includes('Four Up')).click()`);
await sleep(300);
await evalJs(`[...document.querySelectorAll('#sizeBtns .pill')].find(b => b.textContent.includes('Square')).click()`);
await sleep(300);
const sq = await evalJs(`[document.getElementById('previewCanvas').width, document.getElementById('previewCanvas').height]`);
console.log('preview canvas after Square switch:', JSON.stringify(sq));
await evalJs(`[...document.querySelectorAll('#sizeBtns .pill')].find(b => b.textContent.includes('Wide')).click()`);
await sleep(300);

// drag-pan the hero panel a little, then export
await evalJs(`document.getElementById('exportBtn').click()`);
let files = [];
for (let i = 0; i < 20; i++) {
  await sleep(500);
  files = readdirSync(DL).filter((f) => f.endsWith('.png'));
  if (files.length > 0) break;
}
console.log('downloaded:', JSON.stringify(files));
if (files.length === 0) throw new Error('no PNG download appeared');
const png = readFileSync(`${DL}/${files[0]}`);
console.log('PNG magic ok:', png[0] === 0x89 && png[1] === 0x50 && png[2] === 0x4e && png[3] === 0x47);
console.log('PNG bytes:', png.length, 'w/h from IHDR:', png.readUInt32BE(16), 'x', png.readUInt32BE(20));
console.log('PLAY-TEST OK');
chrome.kill();
process.exit(0);
